"""Output parser for dl-optim-mup-parametrization (predict-then-score).

Scored metrics come ONLY from lines the run script emits AFTER the untrusted process has exited,
tagged with a nonce it minted before any submission code ran (first matching line wins for each kind):

    MLSB_RUN_TOKEN=<nonce>                (first line)
    FINAL_METRICS[<nonce>]: k=v ...       (or "INVALID ..." on failure)
    TEST_SHA[<nonce>]: <sha256 of the raw test images the container scored>
    PRED[<nonce>]: transfer <base64 uint8[10000]>
    PRED[<nonce>]: target_best <base64 uint8[10000]>

Test accuracy is computed HERE against the held-out labels in holdout/dl-optim-mup-parametrization/
(the image carries the test images without labels).  Scored columns: ``test_acc_<label>`` (accuracy at
the learning rate transferred from the proxy, higher is better) and ``lr_shift_<label>`` (|log2| drift of
the best learning rate from the proxy width to this one, lower is better).  ``train_loss_gap``,
``test_acc_best``, ``train_loss``, ``log2_lr_*``, ``steps_run``, ``charged_steps`` are informational.
"""
from __future__ import annotations

import base64
import math
import re
import sys
from pathlib import Path

import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
# Only reach for the repo checkout when mlsbench is genuinely absent.
# Under Harbor this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/,
# so a __file__-derived PROJECT_ROOT is /tmp and this would put an
# agent-writable directory at the front of the verifier's sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(PROJECT_ROOT / "src"))
from mlsbench.agent.parsers import OutputParser, ParseResult  # noqa: E402
from mlsbench.holdout import load_holdout_module  # noqa: E402

_TASK = "dl-optim-mup-parametrization"
_HERE = Path(__file__).resolve().parent
dgp = load_holdout_module("dl-optim-mup-parametrization", __file__)  # noqa: E402

_TOKEN_RE = re.compile(r"^MLSB_RUN_TOKEN=([0-9a-f]{8,64})$")
_PAIR_RE = re.compile(r"(\w+)=(-?[\d.]+(?:[eE][+-]?\d+)?|nan|inf|-inf)")
_RANGES = {
    "train_loss_gap": (0.0, 100.0), "train_loss": (0.0, 100.0), "lr_shift": (0.0, 64.0),
    "log2_lr_proxy": (-64.0, 64.0), "log2_lr_target": (-64.0, 64.0), "steps_run": (0.0, 1e9),
    "charged_steps": (0.0, 1e9), "diverged": (0.0, 1.0), "n_diverged_target": (0.0, 1e3),
    "t_rule": (0.0, 1e6), "mu_readout": (0.0, 1.0),
}


class Parser(OutputParser):
    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        fb: list = []
        metrics: dict = {}
        lines = [l.strip() for l in raw_output.splitlines()]
        for l in lines:
            if l.startswith(("SETUP:", "SELECT:", "RULE:", "RULE_ERROR", "RULE_CHARGE")):
                fb.append(l)
        sweeps = [l for l in lines if l.startswith("SWEEP:")]
        if sweeps:
            fb.append("LR sweep (%s):\n%s" % (cmd_label, "\n".join(sweeps[-20:])))
        token = None
        for l in lines:
            m = _TOKEN_RE.match(l)
            if m:
                token = m.group(1); break
        if token is None:
            fb.append("No run token for %s; the run script did not start." % cmd_label)
            return ParseResult(feedback="\n".join(fb) or raw_output[-3000:], metrics={})
        esc = re.escape(token)
        final_re = re.compile(r"^FINAL_METRICS\[" + esc + r"\]:\s*(.*)$")
        sha_re = re.compile(r"^TEST_SHA\[" + esc + r"\]:\s*([0-9a-f]{64})$")
        pred_re = re.compile(r"^PRED\[" + esc + r"\]:\s*(\w+)\s+([A-Za-z0-9+/=]+)$")
        final = sha = None
        preds: dict = {}
        for l in lines:                       # FIRST matching line wins for each kind (never last-wins)
            m = final_re.match(l)
            if m:
                if final is None:
                    final = m.group(1).strip()
                continue
            m = sha_re.match(l)
            if m:
                if sha is None:
                    sha = m.group(1)
                continue
            m = pred_re.match(l)
            if m:
                preds.setdefault(m.group(1), m.group(2))
        if final is None:
            fb.append("No FINAL_METRICS marker for %s; the run did not complete." % cmd_label)
            return ParseResult(feedback="\n".join(fb), metrics={})
        if final.upper().startswith("INVALID"):
            fb.append("Run %s produced no valid result (%s)." % (cmd_label, final))
            return ParseResult(feedback="\n".join(fb), metrics={})
        for key, raw in _PAIR_RE.findall(final):
            if key in _RANGES:
                v = float(raw.lower()); lo, hi = _RANGES[key]
                if math.isfinite(v) and lo <= v <= hi:
                    metrics[f"{key}_{cmd_label}"] = v
        if sha != dgp.TEST_IMAGES_SHA256:
            fb.append("Run %s scored a test set whose image digest does not match the reference; not scored." % cmd_label)
            return ParseResult(feedback="\n".join(fb), metrics={})
        for name, col in (("transfer", "test_acc"), ("target_best", "test_acc_best")):
            payload = preds.get(name)
            if payload is None:
                continue
            try:
                pred = np.frombuffer(base64.b64decode(payload), dtype=np.uint8)
            except Exception:
                continue
            acc = dgp.score_predictions(pred)
            if acc is not None:
                metrics[f"{col}_{cmd_label}"] = acc
        if f"test_acc_{cmd_label}" not in metrics or f"lr_shift_{cmd_label}" not in metrics:
            fb.append("Run %s: marker present but no scoreable test_acc / lr_shift; not scored." % cmd_label)
            return ParseResult(feedback="\n".join(fb), metrics={})
        fb.append("Final metrics (%s): " % cmd_label + ", ".join("%s=%.4f" % (k, v) for k, v in sorted(metrics.items())))
        return ParseResult(feedback="\n".join(fb), metrics=metrics)
